"""Modified UTF-7 codec for IMAP mailbox names (RFC 3501 section 5.1.3)."""
import base64


def decode(name: str) -> str:
    result = []
    pending = None
    for ch in name:
        if pending is None:
            if ch == "&":
                pending = ""
            else:
                result.append(ch)
        else:
            if ch == "-":
                if pending == "":
                    result.append("&")
                else:
                    b64 = pending.replace(",", "/")
                    b64 += "=" * (-len(b64) % 4)
                    result.append(base64.b64decode(b64).decode("utf-16-be"))
                pending = None
            else:
                pending += ch
    if pending is not None:
        b64 = pending.replace(",", "/")
        b64 += "=" * (-len(b64) % 4)
        result.append(base64.b64decode(b64).decode("utf-16-be"))
    return "".join(result)


def encode(name: str) -> str:
    result = []
    buffer = []

    def flush():
        if buffer:
            raw = "".join(buffer).encode("utf-16-be")
            b64 = base64.b64encode(raw).decode("ascii").rstrip("=").replace("/", ",")
            result.append("&" + b64 + "-")
            buffer.clear()

    for ch in name:
        if 0x20 <= ord(ch) <= 0x7E:
            flush()
            if ch == "&":
                result.append("&-")
            else:
                result.append(ch)
        else:
            buffer.append(ch)
    flush()
    return "".join(result)

