def _build_search_criteria(from_addr, subject, keyword, since_days, unseen_only):
    """Build IMAP SEARCH criteria.

    FROM/SINCE/UNSEEN are always ASCII-safe and sent as plain quoted args.
    SUBJECT/TEXT may contain non-ASCII (e.g. Chinese) text, which imaplib
    cannot encode as a plain arg (it forces ASCII). For a non-ASCII value we
    instead send it as a single IMAP literal ({n}\\r\\n<utf-8 bytes>), which
    per RFC 3501 must be the final argument of the command -- so at most one
    of subject/keyword may be non-ASCII per call, and it's appended last.
    """
    criteria = []
    if unseen_only:
        criteria.append("UNSEEN")
    if from_addr:
        criteria += ["FROM", f'"{from_addr}"']
    if since_days:
        import datetime
        date = (datetime.date.today() - datetime.timedelta(days=since_days)).strftime("%d-%b-%Y")
        criteria += ["SINCE", date]

    literal_field = None  # (IMAP field name, utf-8 encoded value) for the non-ASCII term, if any
    trailing = []
    for field_name, value in (("SUBJECT", subject), ("TEXT", keyword)):
        if not value:
            continue
        if value.isascii():
            trailing += [field_name, f'"{value}"']
        elif literal_field is not None:
            raise ValueError("subject 和 keyword 不能同時使用非 ASCII（例如中文）字元搜尋，請分開查詢")
        else:
            literal_field = (field_name, value.encode("utf-8"))

    criteria += trailing
    literal_bytes = None
    if literal_field is not None:
        criteria.append(literal_field[0])
        literal_bytes = literal_field[1]

    if not criteria:
        criteria = ["ALL"]
    return criteria, literal_bytes


def search_emails(folder="INBOX", from_addr=None, subject=None, keyword=None,
                   since_days=None, unseen_only=False, limit=20):
    conn = connect()
