"""Read-only IMAP access to NTU Exchange mail (mail.ntu.edu.tw)."""
import email
import imaplib
import json
from email.header import decode_header
from pathlib import Path

import keyring

import imap_utf7

HOST = "mail.ntu.edu.tw"
PORT = 993
SERVICE = "ntu-mail-mcp"
CONFIG_PATH = Path.home() / ".ntu-mail-mcp" / "config.json"


class NotConfiguredError(RuntimeError):
    pass


def get_credentials():
    if not CONFIG_PATH.exists():
        raise NotConfiguredError(
            f"找不到設定檔 {CONFIG_PATH}。請先在自己的終端機執行 setup_credentials.py。"
        )
    config = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    username = config["username"]
    password = keyring.get_password(SERVICE, username)
    if not password:
        raise NotConfiguredError(
            f"Windows Credential Manager 裡找不到帳號 {username!r} 的密碼。"
            "請重新執行 setup_credentials.py。"
        )
    return username, password


def connect() -> imaplib.IMAP4_SSL:
    username, password = get_credentials()
    conn = imaplib.IMAP4_SSL(HOST, PORT)
    conn.login(username, password)
    return conn


def decode_mime_words(raw: str) -> str:
    if not raw:
        return ""
    parts = decode_header(raw)
    decoded = []
    for text, charset in parts:
        if isinstance(text, bytes):
            decoded.append(text.decode(charset or "utf-8", errors="replace"))
        else:
            decoded.append(text)
    return "".join(decoded)


def list_folders() -> list[str]:
    conn = connect()
    try:
        status, mailboxes = conn.list()
        if status != "OK":
            raise RuntimeError(f"LIST failed: {status}")
        names = []
        for raw in mailboxes:
            if raw is None:
                continue
            line = raw.decode("utf-8", errors="replace")
            close_paren = line.find(")")
            if not line.startswith("(") or close_paren == -1:
                continue
            rest = line[close_paren + 1:].strip()
            # rest is now: "<delimiter>" <mailbox name>
            if not rest.startswith('"'):
                continue
            delim_end = rest.find('"', 1)
            if delim_end == -1:
                continue
            name = rest[delim_end + 1:].strip()
            if name.startswith('"') and name.endswith('"'):
                name = name[1:-1]
            names.append(imap_utf7.decode(name))
        return names
    finally:
        conn.logout()


