"""Read-only IMAP access to NTU Exchange mail (mail.ntu.edu.tw)."""
import email
import imaplib
import json
from email.header import decode_header
from pathlib import Path

import keyring

import imap_utf7

HOST = "mail.ntu.edu.tw"
PORT = 993
SERVICE = "ntu-mail-mcp"
CONFIG_PATH = Path.home() / ".ntu-mail-mcp" / "config.json"


class NotConfiguredError(RuntimeError):
    pass


def get_credentials():
    if not CONFIG_PATH.exists():
        raise NotConfiguredError(
            f"找不到設定檔 {CONFIG_PATH}。請先在自己的終端機執行 setup_credentials.py。"
        )
    config = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    username = config["username"]
    password = keyring.get_password(SERVICE, username)
    if not password:
        raise NotConfiguredError(
            f"Windows Credential Manager 裡找不到帳號 {username!r} 的密碼。"
            "請重新執行 setup_credentials.py。"
        )
    return username, password


def connect() -> imaplib.IMAP4_SSL:
    username, password = get_credentials()
    conn = imaplib.IMAP4_SSL(HOST, PORT)
    conn.login(username, password)
    return conn


def decode_mime_words(raw: str) -> str:
    if not raw:
        return ""
    parts = decode_header(raw)
    decoded = []
    for text, charset in parts:
        if isinstance(text, bytes):
            decoded.append(text.decode(charset or "utf-8", errors="replace"))
        else:
            decoded.append(text)
    return "".join(decoded)


def list_folders() -> list[str]:
    conn = connect()
    try:
        status, mailboxes = conn.list()
        if status != "OK":
            raise RuntimeError(f"LIST failed: {status}")
        names = []
        for raw in mailboxes:
            if raw is None:
                continue
            line = raw.decode("utf-8", errors="replace")
            close_paren = line.find(")")
            if not line.startswith("(") or close_paren == -1:
                continue
            rest = line[close_paren + 1:].strip()
            # rest is now: "<delimiter>" <mailbox name>
            if not rest.startswith('"'):
                continue
            delim_end = rest.find('"', 1)
            if delim_end == -1:
                continue
            name = rest[delim_end + 1:].strip()
            if name.startswith('"') and name.endswith('"'):
                name = name[1:-1]
            names.append(imap_utf7.decode(name))
        return names
    finally:
        conn.logout()


def _build_ascii_criteria(from_addr, since_days, unseen_only):
    """Build IMAP SEARCH criteria from the fields that are always ASCII-safe."""
    criteria = []
    if unseen_only:
        criteria.append("UNSEEN")
    if from_addr:
        criteria += ["FROM", f'"{from_addr}"']
    if since_days:
        import datetime
        date = (datetime.date.today() - datetime.timedelta(days=since_days)).strftime("%d-%b-%Y")
        criteria += ["SINCE", date]
    return criteria or ["ALL"]


def _fetch_header(conn, uid):
    status, msg_data = conn.uid(
        "FETCH", uid, "(BODY.PEEK[HEADER.FIELDS (FROM SUBJECT DATE TO)])"
    )
    if status != "OK" or not msg_data or msg_data[0] is None:
        return None
    return email.message_from_bytes(msg_data[0][1])


def _summarize(uid, msg) -> dict:
    return {
        "uid": uid.decode(),
        "from": decode_mime_words(msg.get("From", "")),
        "to": decode_mime_words(msg.get("To", "")),
        "subject": decode_mime_words(msg.get("Subject", "")),
        "date": msg.get("Date", ""),
    }


def search_emails(folder="INBOX", from_addr=None, subject=None, keyword=None,
                   since_days=None, unseen_only=False, limit=20, scan_limit=200):
    """Search a folder for matching messages, newest first.

    NTU's IMAP server only supports SEARCH with charset US-ASCII (it rejects
    UTF-8), so it cannot server-side search non-ASCII subject/keyword text.
    When subject or keyword contains non-ASCII (e.g. Chinese) characters,
    this instead pulls up to `scan_limit` candidate messages (narrowed by
    from_addr/since_days/unseen_only if given) and filters them locally by
    substring match, which is slower and only looks back `scan_limit` messages.
    """
    conn = connect()
    try:
        status, _ = conn.select(imap_utf7.encode(folder), readonly=True)
        if status != "OK":
            raise RuntimeError(f"無法開啟資料夾 {folder!r}（status={status}）")

        ascii_ok = (not subject or subject.isascii()) and (not keyword or keyword.isascii())

        if ascii_ok:
            criteria = _build_ascii_criteria(from_addr, since_days, unseen_only)
            if subject:
                criteria += ["SUBJECT", f'"{subject}"']
            if keyword:
                criteria += ["TEXT", f'"{keyword}"']
            status, data = conn.uid("SEARCH", *criteria)
            if status != "OK":
                raise RuntimeError(f"SEARCH failed: {status}")
            uids = data[0].split()
            uids = uids[-limit:] if limit else uids
            uids.reverse()  # newest first

            results = []
            for uid in uids:
                msg = _fetch_header(conn, uid)
                if msg is not None:
                    results.append(_summarize(uid, msg))
            return results

        # Local-filter fallback for non-ASCII subject/keyword.
        criteria = _build_ascii_criteria(from_addr, since_days, unseen_only)
        status, data = conn.uid("SEARCH", *criteria)
        if status != "OK":
            raise RuntimeError(f"SEARCH failed: {status}")
        uids = data[0].split()
        uids.reverse()  # newest first
        uids = uids[:scan_limit]

        results = []
        for uid in uids:
            if keyword:
                status, msg_data = conn.uid("FETCH", uid, "(BODY.PEEK[])")
                if status != "OK" or not msg_data or msg_data[0] is None:
                    continue
                msg = email.message_from_bytes(msg_data[0][1])
                haystack = decode_mime_words(msg.get("Subject", "")) + "\n" + _extract_body(msg)
            else:
                msg = _fetch_header(conn, uid)
                if msg is None:
                    continue
                haystack = decode_mime_words(msg.get("Subject", ""))

            if subject and subject not in decode_mime_words(msg.get("Subject", "")):
                continue
            if keyword and keyword not in haystack:
                continue

            results.append(_summarize(uid, msg))
            if len(results) >= limit:
                break
        return results
    finally:
        conn.logout()


def _extract_body(msg: email.message.Message) -> str:
    if msg.is_multipart():
        plain = None
        html = None
        for part in msg.walk():
            content_type = part.get_content_type()
            disposition = str(part.get("Content-Disposition") or "")
            if "attachment" in disposition:
                continue
            if content_type == "text/plain" and plain is None:
                plain = part.get_payload(decode=True)
                plain_charset = part.get_content_charset() or "utf-8"
                plain = plain.decode(plain_charset, errors="replace") if plain else None
            elif content_type == "text/html" and html is None:
                html = part.get_payload(decode=True)
                html_charset = part.get_content_charset() or "utf-8"
                html = html.decode(html_charset, errors="replace") if html else None
        if plain:
            return plain
        if html:
            return html
        return ""
    else:
        payload = msg.get_payload(decode=True)
        charset = msg.get_content_charset() or "utf-8"
        return payload.decode(charset, errors="replace") if payload else ""


def _list_attachments(msg: email.message.Message) -> list[str]:
    names = []
    if msg.is_multipart():
        for part in msg.walk():
            disposition = str(part.get("Content-Disposition") or "")
            if "attachment" in disposition:
                filename = part.get_filename()
                if filename:
                    names.append(decode_mime_words(filename))
    return names


def get_email(uid: str, folder="INBOX"):
    conn = connect()
    try:
        status, _ = conn.select(imap_utf7.encode(folder), readonly=True)
        if status != "OK":
            raise RuntimeError(f"無法開啟資料夾 {folder!r}（status={status}）")

        status, msg_data = conn.uid("FETCH", uid, "(BODY.PEEK[])")
        if status != "OK" or not msg_data or msg_data[0] is None:
            raise RuntimeError(f"找不到 UID {uid} 的信件")

        raw = msg_data[0][1]
        msg = email.message_from_bytes(raw)
        return {
            "uid": uid,
            "from": decode_mime_words(msg.get("From", "")),
            "to": decode_mime_words(msg.get("To", "")),
            "subject": decode_mime_words(msg.get("Subject", "")),
            "date": msg.get("Date", ""),
            "body": _extract_body(msg),
            "attachments": _list_attachments(msg),
        }
    finally:
        conn.logout()

