// 20201001 signR2
function sign(t, Arg) {

    $('#msgModal').modal('show');
    $('#msgModalLabel').text('訊息');
    $('#msg').text('簽到退執行中...');

    if (Arg != '1') { Arg = '0'; }

    var d = {
        type: '6',
        t: t,
        otA: Arg    //
    };

    $.ajax({
        type: "POST",
        url: "ajax/signInR2.ashx",
        data: d,
        dataType: 'json',
        cache: false,
        success: function (d) {

            // if (console) console.log(d);
            var RES = d[0];
            var tMsg = RES.msg;

            // 您不能在校外簽到退

            if (RES.t == '-1') {
                $('#msgModalLabel').text('錯誤訊息');
                $('#msg').text(RES.msg);
                // $('#msg').append('</br>' + RES.d);

                if (console) console.log(tMsg.substring(0, 3));
                if (tMsg.substring(0, 3) >= '您不能') {
                    if (console) console.log(d);
                    $('#msg').append('</br></br>1. 線上簽到退無法使用學校無線網路。</br>2. 如需申請駐外人員簽到等請聯絡人事管理單位。');
                }
            }
            else {
                $('#msgModalLabel').text('系統訊息');
                $('#msg').text(RES.msg);
                // $('#msg').append('</br>' + RES.d);

                var s = 0;
                if (t == '1' || t == '4') {
                    s = 1;
                }
                else {
                    s = 2;
                }

                ajaxGetSignTime(s);
            }
        },
        error: function () {
            $('#msgModalLabel').text('錯誤訊息');
            $('#msg').text('與伺服器連結失敗，請再試看看。');
        }
    });
}


function initBtn0() {
    $("#btSign").unbind("click");
    $("#btSign2").unbind("click");

    $("#btcSign").unbind("click");
    $("#btreSign").unbind("click");
}


// 20200617
function ajaxOtCheck(Arg) {

    var ResT = "[{}]";

    var Res = $.ajax({ url: "ajax/signInR2.ashx", type: "POST", data: { type: 'OTC', Agr:Arg }, async: false, dataType: 'json' }).responseJSON;

    if ((typeof (Res) != "undefined" && Res.length == 1)) {
        return Res[0];
    }
    else { return ResT; }

}


