# -*- coding: utf-8 -*-
"""Per-sender response profile overrides.

A profile lets specific Slack user IDs get different off_topic /
insufficient_info / can_answer handling than the global default. Anyone not
covered by a profile uses the default behavior in bot.py unchanged.

config.json shape:
{
  "response_profiles": [
    {
      "name": "vip",
      "user_ids": ["U0AD3CNMP52"],
      "off_topic": "custom fixed text, optional",
      "insufficient_info": {"mode": "fixed", "text": "custom fixed text"} or {"mode": "ai"},
      "can_answer": {"requires_approval": true}
    }
  ]
}
Any field left out of a profile falls back to the global default for that category.
"""


def find_profile(profiles: list[dict], user_id: str) -> dict | None:
    for profile in profiles:
        if user_id in profile.get("user_ids", []):
            return profile
    return None


def get_off_topic_text(profile: dict | None, default: str) -> str:
    if profile and profile.get("off_topic"):
        return profile["off_topic"]
    return default


def get_insufficient_info_mode(profile: dict | None) -> dict:
    """Returns {"mode": "ai"|"fixed", "text": str|None}."""
    if profile and "insufficient_info" in profile:
        cfg = profile["insufficient_info"]
        if isinstance(cfg, str):
            return {"mode": "fixed", "text": cfg}
        return {"mode": cfg.get("mode", "fixed"), "text": cfg.get("text")}
    return {"mode": "ai", "text": None}


def requires_approval(profile: dict | None) -> bool:
    if profile and "can_answer" in profile:
        return bool(profile["can_answer"].get("requires_approval", True))
    return True

