file.content:
# -*- coding: utf-8 -*-
"""Per-channel content-type routing: when a message in a given channel is
about a configured topic, route it to whoever's responsible for that topic
in that channel -- regardless of who asked. Different from profiles.py,
which is keyed by the *asker*, not the channel/content-type.

config.json shape:
{
  "channel_routing": {
    "C09E45B3KAM": [
      {
        "name": "frontend_content",
        "description": "前端介面文字內容需要修改調整（例如介面說明文字、UI文案、按鈕文字等內容更新）",
        "responsible_user_id": "U0742DC5CQM",
        "reply_template": "收到！這是前端內容修調的需求，再麻煩 {mention} 協助看一下 😊"
      }
    ]
  }
}
Find a channel's ID by right-clicking the channel name in Slack -> "Copy link"
-> the ID is the last segment of the URL (starts with C).

reply_template must contain the literal "{mention}" placeholder -- it's
substituted in Python with the real <@USER_ID> tag, never generated by the
AI, so a routing reply can never tag the wrong person or produce broken
mention syntax.
"""


def get_channel_routes(channel_routing: dict, channel_id: str) -> list[dict]:
    return channel_routing.get(channel_id, [])


def get_route_reply(routes: list[dict], name: str) -> str | None:
    for route in routes:
        if route.get("name") == name:
            mention = f"<@{route['responsible_user_id']}>"
            return route["reply_template"].replace("{mention}", mention)
    return None

