}
Find a channel's ID by right-clicking the channel name in Slack -> "Copy link"
-> the ID is the last segment of the URL (starts with C).

responsible_user_id can be a single ID or a comma-separated list of IDs
("U0123,U0456") -- {mention} expands to every one of them, space-separated.

reply_template must contain the literal "{mention}" placeholder -- it's
substituted in Python with the real <@USER_ID> tag(s), never generated by
the AI, so a routing reply can never tag the wrong person or produce broken
mention syntax.
"""


def get_channel_routes(channel_routing: dict, channel_id: str) -> list[dict]:
    return channel_routing.get(channel_id, [])


def get_route_reply(routes: list[dict], name: str) -> str | None:
    for route in routes:
        if route.get("name") == name:
            user_ids = [uid.strip() for uid in route["responsible_user_id"].split(",") if uid.strip()]
            mention = " ".join(f"<@{uid}>" for uid in user_ids)
            return route["reply_template"].replace("{mention}", mention)
    return None

