"""Local JSON store for drafts awaiting Light's approval via Slack DM.

Keyed by the ts of the DM message the bot sent Light with the draft --
when Light replies in-thread to that DM, event["thread_ts"] gives us back
this same key, so there's no need to parse an ID out of his reply text.
"""
import json
import threading
from datetime import datetime, timedelta, timezone
from pathlib import Path

STORE_PATH = Path.home() / ".slack-light-bot" / "pending.json"
RETENTION_DAYS = 30
_lock = threading.Lock()


def _load() -> dict:
    if not STORE_PATH.exists():
        return {}
    return json.loads(STORE_PATH.read_text(encoding="utf-8"))


def _prune_old(data: dict) -> dict:
    cutoff = datetime.now(timezone.utc) - timedelta(days=RETENTION_DAYS)
    kept = {}
    for key, record in data.items():
        try:
            created = datetime.fromisoformat(record["created_at"])
        except (KeyError, ValueError):
            continue  # malformed record, drop it too
        if created >= cutoff:
            kept[key] = record
    return kept


def _save(data: dict) -> None:
    STORE_PATH.parent.mkdir(parents=True, exist_ok=True)
    data = _prune_old(data)
    STORE_PATH.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")


def add_pending(dm_message_ts: str, *, channel_id: str, message_ts: str,
                 asker_user_id: str, asker_text: str, draft_reply: str) -> None:
    with _lock:
        data = _load()
        data[dm_message_ts] = {
            "channel_id": channel_id,
            "message_ts": message_ts,
            "asker_user_id": asker_user_id,
            "asker_text": asker_text,
            "draft_reply": draft_reply,
            "status": "pending",
            "created_at": datetime.now(timezone.utc).isoformat(),
        }
        _save(data)


def get_pending(dm_message_ts: str) -> dict | None:
    with _lock:
        return _load().get(dm_message_ts)


def resolve_pending(dm_message_ts: str, status: str) -> None:
    with _lock:
        data = _load()
        if dm_message_ts in data:
            data[dm_message_ts]["status"] = status
            _save(data)


def list_pending() -> dict:
    with _lock:
        return {k: v for k, v in _load().items() if v["status"] == "pending"}

